class UnbalancedLedgerError(Exception):
    """Raised when the sum of debits does not equal the sum of credits in a transaction."""
    pass


class DoubleEntryBalanceGuard:
    """Enforces double-entry bookkeeping balance constraints (sum of debits == sum of credits)."""

    def __init__(self, debits=None, credits=None):
        self.debits = list(debits) if debits is not None else []
        self.credits = list(credits) if credits is not None else []

    def _extract_amount(self, item):
        """Helper to extract and convert a numeric amount from various item types (dicts, objects, or raw numbers/strings)."""
        if isinstance(item, (int, float)):
            return item
        if isinstance(item, str):
            try:
                # Try converting string to float/int
                return float(item) if '.' in item else int(item)
            except ValueError:
                raise TypeError(f"Could not convert string amount '{item}' to a number.")
        if isinstance(item, dict):
            for key in ("amount", "value", "debit", "credit"):
                if key in item:
                    return self._extract_amount(item[key])
        if hasattr(item, "amount"):
            return self._extract_amount(item.amount)
        if hasattr(item, "value"):
            return self._extract_amount(item.value)

        # Fallback to direct conversion
        try:
            return float(item)
        except (TypeError, ValueError):
            raise TypeError(f"Unsupported operand type for amount: {type(item)}")

    def validate(self, debits=None, credits=None):
        """Validates that the sum of debits equals the sum of credits.

        Can take debits and credits as arguments or use the instance attributes.
        Raises UnbalancedLedgerError if they do not balance.
        """
        d = debits if debits is not None else self.debits
        c = credits if credits is not None else self.credits

        total_debits = sum(self._extract_amount(item) for item in d)
        total_credits = sum(self._extract_amount(item) for item in c)

        # Use a small tolerance for floating-point comparisons if necessary, 
        # but exact equality or close check can be done.
        if total_debits != total_credits:
            raise UnbalancedLedgerError(
                f"Unbalanced transaction: debits sum to {total_debits}, "
                f"while credits sum to {total_credits}."
            )
        return True

    def post_transaction(self, transaction=None, debits=None, credits=None):
        """Posts a transaction after validating that debits equal credits.

        Accepts either a transaction object/iterable containing debits and credits,
        or separate debits and credits arguments/instance attributes.
        """
        if transaction is not None:
            if isinstance(transaction, dict):
                d = transaction.get("debits", transaction.get("debit", []))
                c = transaction.get("credits", transaction.get("credit", []))
            elif hasattr(transaction, "debits") and hasattr(transaction, "credits"):
                d = transaction.debits
                c = transaction.credits
            elif isinstance(transaction, (list, tuple)) and len(transaction) == 2:
                d, c = transaction
            else:
                d, c = self.debits, self.credits
        else:
            d = debits if debits is not None else self.debits
            c = credits if credits is not None else self.credits

        self.validate(debits=d, credits=c)
        return True
